'use strict';
// ===== MAPS =====  Every battlefield is a ready-made picture: assets/maps/<id>.png (2800 x 1000).
// Opaque pixels = solid ground, see-through pixels = air. No terrain is generated while playing, so maps load instantly.
// MAP_RUNS (bottom of this file) holds the same shape as lists of solid runs per column, because a game opened as a local file can't read pixels back out of a PNG.
// Each map: id, name, desc, bg (sky: day / sunset / night), img (the PNG), thumb (small menu picture).
// To add a map: paint a 2800x1000 PNG with transparent sky, put it in assets/maps, add a line below. The sea is at y = 922.
const MAPS = [
  { id: 'hills',     name: 'Green Hills',     desc: 'Classic rolling hills with caves and floating rocks',        bg: 'day',    img: 'maps/hills.png' },
  { id: 'alps',      name: 'Alpine Range',    desc: 'Tall snowy peaks of very different heights',                 bg: 'day',    img: 'maps/alps.png' },
  { id: 'twinpeaks', name: 'Twin Giants',     desc: 'Two huge mountains with a deep valley between them',         bg: 'sunset', img: 'maps/twinpeaks.png' },
  { id: 'mesas',     name: 'Desert Mesas',    desc: 'Flat-topped rock towers, tall and short, with gaps between', bg: 'sunset', img: 'maps/mesas.png' },
  { id: 'isles',     name: 'Sky Isles',       desc: 'No mainland: islands at every height above the sea',         bg: 'day',    img: 'maps/isles.png' },
  { id: 'volcano',   name: 'Ember Volcano',   desc: 'A big cracked volcano with glowing lava veins',              bg: 'night',  img: 'maps/volcano.png' },
  { id: 'stairs',    name: 'Stone Stairway',  desc: 'Giant steps climbing from the sea to a high plateau',        bg: 'sunset', img: 'maps/stairs.png' },
  { id: 'caverns',   name: 'Crystal Caverns', desc: 'Thick crystal ground full of tunnels and shafts',            bg: 'night',  img: 'maps/caverns.png' },
  { id: 'skybridge', name: 'Sky Bridge',      desc: 'Two tall cliffs joined by a thin bridge over a valley',      bg: 'sunset', img: 'maps/skybridge.png' },
];
for (const m of MAPS) m.thumb = 'assets/maps/thumb_' + m.id + '.png';
const mapById = id => MAPS.find(m => m.id === id);
const mapPreview = map => map.thumb;   // menu picture = small PNG file, nothing to compute

